-- Update Promotional Email Template with 6 Domains and Signature
INSERT INTO status_email_templates (id, subject, html_body)
VALUES (
    'promotional',
    'Invitation: 2026 Official Internship Program — Vyntyra Consultancy Services',
    '<h2 style="font-size:20px;font-weight:700;color:#0f172a;margin:0 0 20px 0;">Official Internship Invitation</h2><p style="margin:0 0 16px 0;font-size:15px;color:#334155;">Dear {{recipientName}},</p><p style="margin:0 0 16px 0;font-size:15px;color:#334155;line-height:1.7;">Following a comprehensive review of academic credentials and candidate profiles, the talent acquisition committee at <strong>Vyntyra Consultancy Services</strong> is pleased to invite you to apply for our <strong>Official 2026 Internship Program</strong> under <strong>Project VyNexa</strong>.</p><p style="margin:0 0 20px 0;font-size:15px;color:#334155;line-height:1.7;">Project VyNexa is our flagship corporate development program designed to bridge the gap between academic learning and high-stakes corporate execution. Participants collaborate on live international initiatives with structured mentorship from industry experts.</p><div style="background-color:#eff6ff;border-left:4px solid #2563eb;padding:16px 20px;border-radius:0 8px 8px 0;margin:24px 0;">  <div style="font-size:12px;font-weight:700;color:#1e3a8a;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.05em;">Available Domains &amp; Specialization Tracks</div>  <p style="margin:0 0 10px 0;font-size:14px;color:#1e40af;line-height:1.6;">Candidates may apply for placements in any of the following 6 global domains:</p>  <div style="margin-bottom:12px;">    <strong style="color:#0f172a;font-size:14px;">1. Engineering &amp; Technology</strong>    <div style="font-size:13px;color:#334155;margin-top:2px;">Full-Stack, MERN/MEAN, Frontend/Backend, DevOps, Mobile App Dev, Data Engineering, QA, Cybersecurity, AI Engineer.</div>  </div>  <div style="margin-bottom:12px;">    <strong style="color:#0f172a;font-size:14px;">2. Marketing &amp; Growth</strong>    <div style="font-size:13px;color:#334155;margin-top:2px;">Digital Marketing, Content Strategy, SEO/SEM, Social Media, Performance Ads, PR, Email Marketing.</div>  </div>  <div style="margin-bottom:12px;">    <strong style="color:#0f172a;font-size:14px;">3. Customer Operations</strong>    <div style="font-size:13px;color:#334155;margin-top:2px;">Customer Support, Technical Support (L1-L3), Client Success, Service Desk, CX Specialist.</div>  </div>  <div style="margin-bottom:12px;">    <strong style="color:#0f172a;font-size:14px;">4. Research &amp; Development (R&D)</strong>    <div style="font-size:13px;color:#334155;margin-top:2px;">AI/ML, Deep Learning &amp; LLM, Data Science, Robotics, Applied Scientific Research.</div>  </div>  <div style="margin-bottom:12px;">    <strong style="color:#0f172a;font-size:14px;">5. Design &amp; Product</strong>    <div style="font-size:13px;color:#334155;margin-top:2px;">UI/UX, Product Design, Graphic Design, Motion Graphics, Technical Product Management.</div>  </div>  <div style="margin-bottom:12px;">    <strong style="color:#0f172a;font-size:14px;">6. Finance &amp; HR</strong>    <div style="font-size:13px;color:#334155;margin-top:2px;">HR Operations, Payroll, Financial Analyst, Legal/Compliance, Business Development &amp; Strategy.</div>  </div>  <p style="margin:16px 0 0 0;font-size:13px;font-style:italic;color:#1e40af;font-weight:600;">* And many more domains are awaited!</p></div><div style="background-color:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin:24px 0;">  <div style="font-size:11px;font-weight:600;color:#64748b;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:8px;">Program Details &amp; Certification</div>  <p style="margin:0;font-size:14px;color:#0f172a;font-weight:600;">    The internship itself is completely free.  </p>  <p style="margin:8px 0 0 0;font-size:14px;color:#334155;line-height:1.6;">    However, to obtain the official certificate at the end, you must qualify the Certificate Qualification Exam test, which costs <strong>199 INR</strong>. You will receive up to <strong>3 attempts</strong> to qualify the exam.  </p></div><p style="margin:0 0 12px 0;font-size:15px;color:#334155;font-weight:600;">Exclusive Premium Corporate Benefits:</p><ul style="margin:0 0 24px 0;padding-left:24px;font-size:15px;color:#334155;line-height:1.6;">  <li>A <strong>Dedicated Mentor</strong> to guide you through your professional journey.</li>  <li>A <strong>Dedicated Dashboard</strong> for interns to track tasks, progress, and shifts.</li>  <li><strong>Corporate standard Industry Collaborative tasks</strong> simulating real-world scenarios.</li>  <li>A <strong>Corporate environment</strong> to prepare you for the global professional world.</li>  <li><strong>Priority Guidance and doubt solving</strong> available on request.</li>  <li><strong>ISO aligned tasks</strong> based strictly on your selected domain.</li>  <li>And many more premium corporate benefits.</li></ul><p style="margin:0 0 24px 0;font-size:15px;color:#334155;">Click the button below to review full program details and submit your application on our official careers portal:</p><a href="https://careers.vyntyraconsultancyservices.in/?apply=true" target="_blank" style="display:inline-block;background-color:#0f172a;color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;padding:14px 28px;border-radius:6px;">Apply For Internship &rarr;</a><p style="margin:32px 0 0 0;font-size:15px;color:#334155;">Sincerely,</p><img src="https://portal.vyntyraconsultancyservices.in/signature.png" alt="Jami Eswar Anil Kumar - Signature" style="height: 60px; margin: 12px 0; display: block;" /><p style="margin:4px 0 0 0;font-size:15px;font-weight:600;color:#0f172a;">Jami Eswar Anil Kumar</p><p style="margin:2px 0 0 0;font-size:13px;font-weight:500;color:#64748b;">Founder &amp; Managing Director<br>Vyntyra Consultancy Services</p>'
)
ON CONFLICT (id) DO UPDATE 
SET subject = EXCLUDED.subject, html_body = EXCLUDED.html_body;
